contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(address caller, string calldata desc) public {
        bool successBefore;
        bool successAfter;
        (successBefore,) = address(c).call(abi.encodeWithSignature("newEmergencyOracle(string)", desc));
        (successAfter,) = address(c).call(abi.encodeWithSignature("newEmergencyOracle(string)", desc));
        assert(successBefore == false && successAfter == true);
