pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address jojoTeam = address(0x1234);
    function setUp() public {
        c = new C();
        // Set jojoTeam to a known address for pranking
        vm.store(address(c), bytes32(uint256(0)), bytes32(uint256(uint160(jojoTeam))));
    }
    function testFuzz_property(string calldata description) public {
        vm.prank(jojoTeam);
        c.newEmergencyOracle(description);
        // The deployed oracle is the first log from NewEmergencyOracle
        vm.recordLogs();
        vm.prank(jojoTeam);
        c.newEmergencyOracle("dummy");
        Vm.Log[] memory entries = vm.getRecordedLogs();
        // Parse address from the first log (topic1 is the owner emitted in NewEmergencyOracle)
        address deployedOracle = address(uint160(uint256(entries[0].topics[1])));
        EmergencyOracle oracle = EmergencyOracle(deployedOracle);
        assertTrue(oracle.owner() == jojoTeam);
    }
}

